  1	/**
  2	 * tests/plugins/plugin-runner.test.ts
  3	 *
  4	 * Unit tests for the plugin runner — src/plugins/runner.ts
  5	 *
  6	 * Covers all six hook functions (runSuiteInit, runPartials, runBuildContext,
  7	 * runPersonaPartials, runPostRender, runValidate) with three plugin-count
  8	 * scenarios:
  9	 *   - 0 plugins: runner handles empty list gracefully
 10	 *   - 1 plugin: single hook invocation works correctly
 11	 *   - 3 plugins: hooks are invoked in registration order and
 12	 *                context/output accumulation across plugins is verified
 13	 *
 14	 * Also covers edge cases: plugins without the relevant hook are skipped,
 15	 * and hook chaining is correct (each plugin receives previous plugin's output).
 16	 */
 17	
 18	import { describe, it, expect, vi } from 'vitest';
 19	import {
 20	  runSuiteInit,
 21	  runPartials,
 22	  runBuildContext,
 23	  runPersonaPartials,
 24	  runPostRender,
 25	  runValidate,
 26	} from '../../src/plugins/runner.js';
 27	import type {
 28	  PersonaBuildPlugin,
 29	  PersonaMetadata,
 30	  SuiteConfig,
 31	  ValidationResult,
 32	} from '../../src/plugins/types.js';
 33	
 34	// ---------------------------------------------------------------------------
 35	// Fixtures
 36	// ---------------------------------------------------------------------------
 37	
 38	/** Minimal SuiteConfig for testing purposes */
 39	const suite: SuiteConfig = {
 40	  srcDir: '/fixtures/sample-suite',
 41	  outVscode: '/out/vscode',
 42	  outClaudeCode: '/out/claude-code',
 43	};
 44	
 45	/** Minimal PersonaMetadata for testing purposes */
 46	const persona: PersonaMetadata = {
 47	  name: 'test-persona',
 48	  displayName: 'Test Persona',
 49	  version: '1.0.0',
 50	};
 51	
 52	// ---------------------------------------------------------------------------
 53	// runSuiteInit
 54	// ---------------------------------------------------------------------------
 55	
 56	describe('runSuiteInit()', () => {
 57	  // 0-plugin scenario
 58	  it('does nothing when the plugin list is empty', () => {
 59	    const sharedMeta: Record<string, unknown> = { key: 'original' };
 60	    // Should not throw and should leave sharedMeta unchanged
 61	    expect(() => runSuiteInit([], suite, sharedMeta)).not.toThrow();
 62	    expect(sharedMeta.key).toBe('original');
 63	  });
 64	
 65	  // 1-plugin scenario
 66	  it('calls onSuiteInit on a single plugin', () => {
 67	    const onSuiteInit = vi.fn();
 68	    const plugin: PersonaBuildPlugin = { name: 'plugin-a', onSuiteInit };
 69	    const sharedMeta: Record<string, unknown> = {};
 70	    runSuiteInit([plugin], suite, sharedMeta);
 71	    expect(onSuiteInit).toHaveBeenCalledOnce();
 72	    expect(onSuiteInit).toHaveBeenCalledWith(suite, sharedMeta);
 73	  });
 74	
 75	  // 1-plugin: mutation
 76	  it('allows a plugin to mutate sharedMeta', () => {
 77	    const plugin: PersonaBuildPlugin = {
 78	      name: 'mutator',
 79	      onSuiteInit(_, meta) {
 80	        meta['injected'] = 'hello';
 81	      },
 82	    };
 83	    const sharedMeta: Record<string, unknown> = {};
 84	    runSuiteInit([plugin], suite, sharedMeta);
 85	    expect(sharedMeta['injected']).toBe('hello');
 86	  });
 87	
 88	  // 3-plugin scenario: invocation order
 89	  it('calls onSuiteInit on 3 plugins in registration order', () => {
 90	    const callOrder: string[] = [];
 91	    const makePlugin = (name: string): PersonaBuildPlugin => ({
 92	      name,
 93	      onSuiteInit() {
 94	        callOrder.push(name);
 95	      },
 96	    });
 97	    const plugins = [makePlugin('first'), makePlugin('second'), makePlugin('third')];
 98	    runSuiteInit(plugins, suite, {});
 99	    expect(callOrder).toEqual(['first', 'second', 'third']);
100	  });

101	
102	  // 3-plugin scenario: mutation accumulates
103	  it('passes the same sharedMeta reference to all plugins — mutations accumulate', () => {
104	    const plugins: PersonaBuildPlugin[] = [
105	      {
106	        name: 'p1',
107	        onSuiteInit(_, meta) {
108	          meta['p1'] = true;
109	        },
110	      },
111	      {
112	        name: 'p2',
113	        onSuiteInit(_, meta) {
114	          meta['p2'] = true;
115	        },
116	      },
117	      {
118	        name: 'p3',
119	        onSuiteInit(_, meta) {
120	          meta['p3'] = true;
121	        },
122	      },
123	    ];
124	    const sharedMeta: Record<string, unknown> = {};
125	    runSuiteInit(plugins, suite, sharedMeta);
126	    expect(sharedMeta).toEqual({ p1: true, p2: true, p3: true });
127	  });
128	
129	  // Skips plugin without the hook
130	  it('skips plugins that do not implement onSuiteInit', () => {
131	    const onSuiteInit = vi.fn();
132	    const plugins: PersonaBuildPlugin[] = [
133	      { name: 'no-hook' },
134	      { name: 'with-hook', onSuiteInit },
135	      { name: 'also-no-hook' },
136	    ];
137	    runSuiteInit(plugins, suite, {});
138	    expect(onSuiteInit).toHaveBeenCalledOnce();
139	  });
140	});
141	
142	// ---------------------------------------------------------------------------
143	// runBuildContext
144	// ---------------------------------------------------------------------------
145	
146	describe('runBuildContext()', () => {
147	  // 0-plugin scenario
148	  it('returns the initial context unchanged when the plugin list is empty', () => {
149	    const initial = { foo: 'bar' };
150	    const result = runBuildContext([], initial, persona, suite);
151	    expect(result).toEqual({ foo: 'bar' });
152	  });
153	
154	  // 1-plugin scenario
155	  it('calls onBuildContext on a single plugin and returns its result', () => {
156	    const plugin: PersonaBuildPlugin = {
157	      name: 'ctx-plugin',
158	      onBuildContext(ctx) {
159	        return { ...ctx, added: 'value' };
160	      },
161	    };
162	    const result = runBuildContext([plugin], { base: 1 }, persona, suite);
163	    expect(result).toEqual({ base: 1, added: 'value' });
164	  });
165	
166	  // 1-plugin: receives correct arguments
167	  it('passes context, persona, and suite to the plugin hook', () => {
168	    const onBuildContext = vi.fn((ctx: Record<string, unknown>) => ctx);
169	    const plugin: PersonaBuildPlugin = { name: 'arg-check', onBuildContext };
170	    const ctx = { x: 1 };
171	    runBuildContext([plugin], ctx, persona, suite);
172	    expect(onBuildContext).toHaveBeenCalledWith(ctx, persona, suite, undefined);
173	  });
174	
175	  // 3-plugin scenario: each plugin receives previous output
176	  it('accumulates context across 3 plugins — each receives the previous plugin\'s output', () => {
177	    const plugins: PersonaBuildPlugin[] = [
178	      {
179	        name: 'p1',
180	        onBuildContext(ctx) {
181	          return { ...ctx, step1: 'done' };
182	        },
183	      },
184	      {
185	        name: 'p2',
186	        onBuildContext(ctx) {
187	          // ctx at this point must include step1 from p1
188	          return { ...ctx, step2: typeof ctx['step1'] === 'string' ? 'has-step1' : 'missing-step1' };
189	        },
190	      },
191	      {
192	        name: 'p3',
193	        onBuildContext(ctx) {
194	          // ctx must include both step1 and step2
195	          const hasBoth = typeof ctx['step1'] === 'string' && typeof ctx['step2'] === 'string';
196	          return { ...ctx, step3: hasBoth ? 'has-both' : 'missing' };
197	        },
198	      },
199	    ];
200	    const result = runBuildContext(plugins, {}, persona, suite);
201	    expect(result['step1']).toBe('done');
202	    expect(result['step2']).toBe('has-step1');
203	    expect(result['step3']).toBe('has-both');
204	  });
205	
206	  // 3-plugin scenario: invocation order verified
207	  it('invokes onBuildContext on 3 plugins in registration order', () => {
208	    const callOrder: string[] = [];
209	    const makePlugin = (name: string): PersonaBuildPlugin => ({
210	      name,
211	      onBuildContext(ctx) {
212	        callOrder.push(name);
213	        return ctx;
214	      },
215	    });
216	    runBuildContext(
217	      [makePlugin('first'), makePlugin('second'), makePlugin('third')],
218	      {},
219	      persona,
220	      suite,
221	    );
222	    expect(callOrder).toEqual(['first', 'second', 'third']);
223	  });
224	
225	  // Skips plugin without the hook
226	  it('skips plugins that do not implement onBuildContext', () => {
227	    const plugins: PersonaBuildPlugin[] = [
228	      { name: 'no-hook' },
229	      {
230	        name: 'with-hook',
231	        onBuildContext(ctx) {
232	          return { ...ctx, touched: true };
233	        },
234	      },
235	      { name: 'also-no-hook' },
236	    ];
237	    const result = runBuildContext(plugins, { original: true }, persona, suite);
238	    expect(result).toEqual({ original: true, touched: true });
239	  });
240	});
241	
242	// ---------------------------------------------------------------------------
243	// runPostRender
244	// ---------------------------------------------------------------------------
245	
246	describe('runPostRender()', () => {
247	  // 0-plugin scenario
248	  it('returns the initial rendered string unchanged when the plugin list is empty', () => {
249	    const result = runPostRender([], 'original content', persona, 'vscode');
250	    expect(result).toBe('original content');
251	  });
252	
253	  // 1-plugin scenario
254	  it('calls onPostRender on a single plugin and returns its result', () => {
255	    const plugin: PersonaBuildPlugin = {
256	      name: 'render-plugin',
257	      onPostRender(output) {
258	        return output + '\n<!-- rendered -->';
259	      },
260	    };
261	    const result = runPostRender([plugin], 'body', persona, 'vscode');
262	    expect(result).toBe('body\n<!-- rendered -->');
263	  });
264	
265	  // 1-plugin: receives correct arguments
266	  it('passes output, persona, and target to the plugin hook', () => {
267	    const onPostRender = vi.fn((output: string) => output);
268	    const plugin: PersonaBuildPlugin = { name: 'arg-check', onPostRender };
269	    runPostRender([plugin], 'text', persona, 'claude-code');
270	    expect(onPostRender).toHaveBeenCalledWith('text', persona, 'claude-code');
271	  });
272	
273	  // 3-plugin scenario: chaining — each plugin receives previous output
274	  it('chains output across 3 plugins — each plugin receives the previous plugin\'s return value', () => {
275	    const plugins: PersonaBuildPlugin[] = [
276	      {
277	        name: 'p1',
278	        onPostRender(output) {
279	          return output + '[p1]';
280	        },
281	      },
282	      {
283	        name: 'p2',
284	        onPostRender(output) {
285	          return output + '[p2]';
286	        },
287	      },
288	      {
289	        name: 'p3',
290	        onPostRender(output) {
291	          return output + '[p3]';
292	        },
293	      },
294	    ];
295	    const result = runPostRender(plugins, 'start', persona, 'vscode');
296	    expect(result).toBe('start[p1][p2][p3]');
297	  });
298	
299	  // 3-plugin scenario: invocation order verified
300	  it('invokes onPostRender on 3 plugins in registration order', () => {
301	    const callOrder: string[] = [];
302	    const makePlugin = (name: string): PersonaBuildPlugin => ({
303	      name,
304	      onPostRender(output) {
305	        callOrder.push(name);
306	        return output;
307	      },
308	    });
309	    runPostRender(
310	      [makePlugin('first'), makePlugin('second'), makePlugin('third')],
311	      '',
312	      persona,
313	      'vscode',
314	    );
315	    expect(callOrder).toEqual(['first', 'second', 'third']);
316	  });
317	
318	  // Skips plugin without the hook
319	  it('skips plugins that do not implement onPostRender', () => {
320	    const plugins: PersonaBuildPlugin[] = [
321	      { name: 'no-hook' },
322	      {
323	        name: 'with-hook',
324	        onPostRender(output) {
325	          return output + '[touched]';
326	        },
327	      },
328	      { name: 'also-no-hook' },
329	    ];
330	    const result = runPostRender(plugins, 'base', persona, 'vscode');
331	    expect(result).toBe('base[touched]');
332	  });
333	
334	  // Target is passed through to each plugin
335	  it('passes the target type to every plugin', () => {
336	    const targets: string[] = [];
337	    const plugin: PersonaBuildPlugin = {
338	      name: 'target-capture',
339	      onPostRender(output, _p, target) {
340	        targets.push(target);
341	        return output;
342	      },
343	    };
344	    runPostRender([plugin, plugin], 'x', persona, 'claude-code');
345	    expect(targets).toEqual(['claude-code', 'claude-code']);
346	  });
347	});
348	
349	// ---------------------------------------------------------------------------
350	// runValidate
351	// ---------------------------------------------------------------------------
352	
353	describe('runValidate()', () => {
354	  // 0-plugin scenario
355	  it('returns an empty array when the plugin list is empty', () => {
356	    const result = runValidate([], persona, suite);
357	    expect(result).toEqual([]);
358	  });
359	
360	  // 1-plugin scenario: returns results
361	  it('returns validation results from a single plugin', () => {
362	    const expected: ValidationResult[] = [
363	      { severity: 'error', message: 'Missing required field' },
364	    ];
365	    const plugin: PersonaBuildPlugin = {
366	      name: 'validator',
367	      onValidate() {
368	        return expected;
369	      },
370	    };
371	    const result = runValidate([plugin], persona, suite);
372	    expect(result).toEqual(expected);
373	  });
374	
375	  // 1-plugin scenario: receives correct arguments
376	  it('passes persona, suite, and target to the plugin hook', () => {
377	    const onValidate = vi.fn(() => [] as ValidationResult[]);
378	    const plugin: PersonaBuildPlugin = { name: 'arg-check', onValidate };
379	    runValidate([plugin], persona, suite, 'vscode');
380	    expect(onValidate).toHaveBeenCalledWith(persona, suite, 'vscode');
381	  });
382	
383	  // 1-plugin scenario: target is forwarded as undefined when not supplied
384	  it('forwards undefined target when no target argument is provided', () => {
385	    const onValidate = vi.fn(() => [] as ValidationResult[]);
386	    const plugin: PersonaBuildPlugin = { name: 'no-target', onValidate };
387	    runValidate([plugin], persona, suite);
388	    expect(onValidate).toHaveBeenCalledWith(persona, suite, undefined);
389	  });
390	
391	  // 1-plugin: returns empty array from plugin
392	  it('returns empty array when plugin\'s onValidate returns []', () => {
393	    const plugin: PersonaBuildPlugin = {
394	      name: 'no-issues',
395	      onValidate() {
396	        return [];
397	      },
398	    };
399	    expect(runValidate([plugin], persona, suite)).toEqual([]);
400	  });

401	
402	  // 3-plugin scenario: flattens results from all plugins
403	  it('collects and flattens ValidationResult from 3 plugins', () => {
404	    const plugins: PersonaBuildPlugin[] = [
405	      {
406	        name: 'p1',
407	        onValidate() {
408	          return [{ severity: 'error', message: 'P1 error' }];
409	        },
410	      },
411	      {
412	        name: 'p2',
413	        onValidate() {
414	          return [
415	            { severity: 'warning', message: 'P2 warning' },
416	            { severity: 'info', message: 'P2 info' },
417	          ];
418	        },
419	      },
420	      {
421	        name: 'p3',
422	        onValidate() {
423	          return [{ severity: 'error', message: 'P3 error' }];
424	        },
425	      },
426	    ];
427	    const result = runValidate(plugins, persona, suite);
428	    expect(result).toHaveLength(4);
429	    expect(result[0]).toEqual({ severity: 'error', message: 'P1 error' });
430	    expect(result[1]).toEqual({ severity: 'warning', message: 'P2 warning' });
431	    expect(result[2]).toEqual({ severity: 'info', message: 'P2 info' });
432	    expect(result[3]).toEqual({ severity: 'error', message: 'P3 error' });
433	  });
434	
435	  // 3-plugin scenario: invocation order verified
436	  it('invokes onValidate on 3 plugins in registration order', () => {
437	    const callOrder: string[] = [];
438	    const makePlugin = (name: string): PersonaBuildPlugin => ({
439	      name,
440	      onValidate() {
441	        callOrder.push(name);
442	        return [];
443	      },
444	    });
445	    runValidate([makePlugin('first'), makePlugin('second'), makePlugin('third')], persona, suite);
446	    expect(callOrder).toEqual(['first', 'second', 'third']);
447	  });
448	
449	  // 3-plugin scenario: mixed — some with hook, some without
450	  it('skips plugins that do not implement onValidate and collects from the rest', () => {
451	    const plugins: PersonaBuildPlugin[] = [
452	      { name: 'no-validate-1' },
453	      {
454	        name: 'validator',
455	        onValidate() {
456	          return [{ severity: 'warning', message: 'check this' }];
457	        },
458	      },
459	      { name: 'no-validate-2' },
460	    ];
461	    const result = runValidate(plugins, persona, suite);
462	    expect(result).toEqual([{ severity: 'warning', message: 'check this' }]);
463	  });
464	
465	  // All 3 severities are preserved
466	  it('preserves all severity levels (error, warning, info)', () => {
467	    const plugin: PersonaBuildPlugin = {
468	      name: 'all-severities',
469	      onValidate() {
470	        return [
471	          { severity: 'error', message: 'an error' },
472	          { severity: 'warning', message: 'a warning' },
473	          { severity: 'info', message: 'an info' },
474	        ];
475	      },
476	    };
477	    const result = runValidate([plugin], persona, suite);
478	    const severities = result.map((r) => r.severity);
479	    expect(severities).toContain('error');
480	    expect(severities).toContain('warning');
481	    expect(severities).toContain('info');
482	  });
483	});
