485	// ---------------------------------------------------------------------------
486	// runPartials
487	// ---------------------------------------------------------------------------
488	
489	describe('runPartials()', () => {
490	  const suiteName = 'test-suite';
491	
492	  // 0-plugin scenario
493	  it('returns the original partials map by identity when the plugin list is empty', () => {
494	    const initial: Record<string, string> = { header: '# Hello' };
495	    const result = runPartials([], initial, suiteName, suite);
496	    expect(result).toBe(initial); // same reference — not just equal
497	  });
498	
499	  // 0-plugin: value equality fallback
500	  it('returns a map equal to the initial map when no plugins implement onPartials', () => {
501	    const initial: Record<string, string> = { footer: 'end' };
502	    const result = runPartials([], initial, suiteName, suite);
503	    expect(result).toEqual({ footer: 'end' });
504	  });
505	
506	  // 1-plugin scenario: single invocation
507	  it('calls onPartials on a single plugin and returns its result', () => {
508	    const plugin: PersonaBuildPlugin = {
509	      name: 'partials-plugin',
510	      onPartials(map) {
511	        return { ...map, injected: 'new partial' };
512	      },
513	    };
514	    const result = runPartials([plugin], { base: 'base content' }, suiteName, suite);
515	    expect(result).toEqual({ base: 'base content', injected: 'new partial' });
516	  });
517	
518	  // 1-plugin: receives correct arguments
519	  it('passes partialsMap, suiteName, and suite to the plugin hook', () => {
520	    const onPartials = vi.fn((map: Record<string, string>) => map);
521	    const plugin: PersonaBuildPlugin = { name: 'arg-check', onPartials };
522	    const initial = { key: 'val' };
523	    runPartials([plugin], initial, suiteName, suite);
524	    expect(onPartials).toHaveBeenCalledWith(initial, suiteName, suite);
525	  });
526	
527	  // Skips plugins without the hook — map passes through unchanged
528	  it('skips plugins that do not implement onPartials — map passes through unchanged', () => {
529	    const plugins: PersonaBuildPlugin[] = [
530	      { name: 'no-hook-1' },
531	      {
532	        name: 'with-hook',
533	        onPartials(map) {
534	          return { ...map, added: 'yes' };
535	        },
536	      },
537	      { name: 'no-hook-2' },
538	    ];
539	    const result = runPartials(plugins, { original: 'keep' }, suiteName, suite);
540	    expect(result).toEqual({ original: 'keep', added: 'yes' });
541	  });
542	
543	  // 3-plugin scenario: accumulating chain
544	  it('accumulates partials across 3 plugins — each plugin receives previous plugin\'s output', () => {
545	    const plugins: PersonaBuildPlugin[] = [
546	      {
547	        name: 'p1',
548	        onPartials(map) {
549	          return { ...map, p1: 'from-p1' };
550	        },
551	      },
552	      {
553	        name: 'p2',
554	        onPartials(map) {
555	          // must include p1's contribution
556	          return { ...map, p2: typeof map['p1'] === 'string' ? 'saw-p1' : 'missing-p1' };
557	        },
558	      },
559	      {
560	        name: 'p3',
561	        onPartials(map) {
562	          const hasBoth = typeof map['p1'] === 'string' && typeof map['p2'] === 'string';
563	          return { ...map, p3: hasBoth ? 'has-both' : 'missing' };
564	        },
565	      },
566	    ];
567	    const result = runPartials(plugins, {}, suiteName, suite);
568	    expect(result['p1']).toBe('from-p1');
569	    expect(result['p2']).toBe('saw-p1');
570	    expect(result['p3']).toBe('has-both');
571	  });
572	
573	  // 3-plugin scenario: invocation order verified
574	  it('invokes onPartials on 3 plugins in registration order', () => {
575	    const callOrder: string[] = [];
576	    const makePlugin = (name: string): PersonaBuildPlugin => ({
577	      name,
578	      onPartials(map) {
579	        callOrder.push(name);
580	        return map;
581	      },
582	    });
583	    runPartials([makePlugin('first'), makePlugin('second'), makePlugin('third')], {}, suiteName, suite);
584	    expect(callOrder).toEqual(['first', 'second', 'third']);
585	  });
586	
587	  // Cross-hook isolation: onPersonaPartials on same plugin is not called
588	  it('does not invoke onPersonaPartials when running runPartials', () => {
589	    const onPersonaPartials = vi.fn((map: Record<string, string>) => map);
590	    const plugin: PersonaBuildPlugin = {
591	      name: 'dual-hook',
592	      onPartials(map) {
593	        return { ...map, suite: 'set' };
594	      },
595	      onPersonaPartials,
596	    };
597	    runPartials([plugin], {}, suiteName, suite);
598	    expect(onPersonaPartials).not.toHaveBeenCalled();
599	  });
600	});

